// Un grafo ralo inventado: 2.000 puntos y 6.000 tramos al azar (semilla fija)
let semilla = 99;
const azar = n => (semilla = (semilla * 16807) % 2147483647) % n;
const V = 2000, E = 6000;
const tramos = new Set();
while (tramos.size < E) {
  const a = azar(V), b = azar(V);
  if (a !== b) tramos.add(Math.min(a, b) * V + Math.max(a, b));   // sin repetir
}

// Las dos representaciones del MISMO grafo
const matriz = new Uint8Array(V * V);                 // V × V celdas, 1 = hay tramo
const lista = Array.from({ length: V }, () => []);    // para cada punto, sus vecinos
for (const k of tramos) {
  const a = Math.floor(k / V), b = k % V;
  matriz[a * V + b] = matriz[b * V + a] = 1;
  lista[a].push(b); lista[b].push(a);
}

// BFS desde el punto 0, contando cuántas celdas o entradas hay que mirar para pedir vecinos
function bfsMatriz() {
  const visto = new Uint8Array(V); visto[0] = 1;
  const cola = [0]; let lecturas = 0;
  for (let i = 0; i < cola.length; i++) {
    const v = cola[i];
    for (let w = 0; w < V; w++) {                     // para hallar los vecinos hay que recorrer la fila entera
      lecturas++;
      if (matriz[v * V + w] && !visto[w]) { visto[w] = 1; cola.push(w); }
    }
  }
  return { alcanzados: cola.length, lecturas };
}
function bfsLista() {
  const visto = new Uint8Array(V); visto[0] = 1;
  const cola = [0]; let lecturas = 0;
  for (let i = 0; i < cola.length; i++) {
    for (const w of lista[cola[i]]) {                 // solo se miran los vecinos que existen
      lecturas++;
      if (!visto[w]) { visto[w] = 1; cola.push(w); }
    }
  }
  return { alcanzados: cola.length, lecturas };
}

console.log(`Memoria: matriz ${(V * V).toLocaleString("es-AR")} celdas; lista ${(V + 2 * E).toLocaleString("es-AR")} entradas (${V} listas + 2 × ${E} tramos)`);
const m = bfsMatriz(), l = bfsLista();
console.log(`BFS con matriz: alcanza ${m.alcanzados} puntos y mira ${m.lecturas.toLocaleString("es-AR")} celdas`);
console.log(`BFS con lista:  alcanza ${l.alcanzados} puntos y mira ${l.lecturas.toLocaleString("es-AR")} entradas`);

// Grafo no dirigido con lista de adyacencia: cada vértice guarda la lista de sus vecinos
class Grafo {
  constructor() { this.vecinos = new Map(); }
  agregarVertice(v) { if (!this.vecinos.has(v)) this.vecinos.set(v, []); }
  agregarArista(a, b) {                        // no dirigida: se anota en las dos listas
    this.agregarVertice(a); this.agregarVertice(b);
    this.vecinos.get(a).push(b);
    this.vecinos.get(b).push(a);
  }
  // BFS: visita por capas, con una cola FIFO. Se marca al ENCOLAR, no al sacar.
  bfs(origen) {
    const distancia = new Map([[origen, 0]]), padre = new Map(), orden = [];
    const cola = [origen];
    for (let i = 0; i < cola.length; i++) {    // «i» marca el frente de la cola
      const v = cola[i];
      orden.push(v);
      for (const w of this.vecinos.get(v)) {
        if (!distancia.has(w)) { distancia.set(w, distancia.get(v) + 1); padre.set(w, v); cola.push(w); }
      }
    }
    return { orden, distancia, padre };
  }
  // DFS: se mete lo más hondo posible y recién entonces retrocede (la recursión usa la pila de llamadas)
  dfs(origen, visitados = new Set(), orden = []) {
    visitados.add(origen); orden.push(origen);
    for (const w of this.vecinos.get(origen)) if (!visitados.has(w)) this.dfs(w, visitados, orden);
    return orden;
  }
  // Componentes conexos: un DFS nuevo cada vez que queda un vértice sin visitar
  componentes() {
    const visto = new Set(), grupos = [];
    for (const v of this.vecinos.keys()) if (!visto.has(v)) grupos.push(this.dfs(v, visto));
    return grupos;
  }
}

const aristas = [["D","A"],["D","B"],["A","C"],["A","E"],["B","E"],["C","F"],["E","F"],["F","G"],["H","I"]];
const g = new Grafo();
for (const [a, b] of aristas) g.agregarArista(a, b);
for (const lista of g.vecinos.values()) lista.sort();   // vecinos en orden alfabético: el recorrido sale siempre igual

const r = g.bfs("D");
console.log("BFS desde D:", r.orden.join(" "));
console.log("tramos desde D:", [...r.distancia].map(([v, d]) => `${v}=${d}`).join(" "));
console.log("DFS desde D:", g.dfs("D").join(" "));

const grupos = g.componentes();
console.log("componentes:", grupos.map(c => `{${c.join(",")}}`).join(" "));
console.log(`ciclos independientes: aristas - vértices + componentes = ${aristas.length} - ${g.vecinos.size} + ${grupos.length} = ${aristas.length - g.vecinos.size + grupos.length}`);

// El camino con menos tramos de D a F, reconstruido con los «padres» que anotó el BFS
const camino = [ "F" ];
while (r.padre.has(camino[0])) camino.unshift(r.padre.get(camino[0]));
console.log("de D a F con menos tramos:", camino.join(" -> "));

// Dependencias de chalk@4.1.2, leídas con `npm view <paquete> dependencies` el 13-11-2026.
// Cada línea dice: «este paquete necesita a estos otros» (aristas dirigidas)
const necesita = {
  "chalk": ["ansi-styles", "supports-color"],
  "ansi-styles": ["color-convert"],
  "supports-color": ["has-flag"],
  "color-convert": ["color-name"],
  "has-flag": [],
  "color-name": [],
};

// DFS con tres estados por vértice: sin visitar, en curso (está en el camino actual) y terminado.
// Un paquete se anota recién cuando ya se anotaron todos los que necesita: ese es un orden válido de instalación.
function ordenDeInstalacion(grafo) {
  const estado = new Map(), orden = [];
  function visitar(p, camino) {
    if (estado.get(p) === "terminado") return;
    if (estado.get(p) === "en curso") throw new Error("hay un ciclo: " + [...camino.slice(camino.indexOf(p)), p].join(" -> "));
    estado.set(p, "en curso");
    for (const q of grafo[p] ?? []) visitar(q, [...camino, p]);
    estado.set(p, "terminado");
    orden.push(p);
  }
  for (const p of Object.keys(grafo)) visitar(p, []);
  return orden;
}

console.log("orden de instalación:", ordenDeInstalacion(necesita).join(", "));

// Un ciclo inventado: a necesita a b, y b necesita a a
try { ordenDeInstalacion({ a: ["b"], b: ["a"] }); } catch (e) { console.log(e.message); }

// Red de rutas con kilómetros INVENTADOS: [desde, hasta, km]
const tramos = [["D","A",4],["D","B",2],["A","C",3],["A","E",2],["B","E",1],["C","F",6],["E","F",2],["F","G",5]];
const vecinos = new Map();
for (const [a, b, km] of tramos) {
  for (const [x, y] of [[a, b], [b, a]]) {
    if (!vecinos.has(x)) vecinos.set(x, []);
    vecinos.get(x).push({ a: y, km });
  }
}
for (const lista of vecinos.values()) lista.sort((p, q) => (p.a < q.a ? -1 : 1));

// 1) BFS: el camino con menos tramos (no mira los km)
const padre = new Map(), visto = new Set(["D"]), cola = ["D"];
for (let i = 0; i < cola.length; i++) {
  for (const { a } of vecinos.get(cola[i])) if (!visto.has(a)) { visto.add(a); padre.set(a, cola[i]); cola.push(a); }
}
const bfs = ["F"];
while (padre.has(bfs[0])) bfs.unshift(padre.get(bfs[0]));
const kmDe = camino => camino.slice(1).reduce((s, v, i) => s + vecinos.get(camino[i]).find(t => t.a === v).km, 0);
console.log(`BFS (menos tramos): ${bfs.join("-")}  ${bfs.length - 1} tramos, ${kmDe(bfs)} km`);

// 2) Probar TODOS los caminos sin repetir puntos (backtracking): sirve acá, explota en redes grandes
const todos = [];
(function buscar(camino) {
  const v = camino[camino.length - 1];
  if (v === "F") { todos.push(camino); return; }
  for (const { a } of vecinos.get(v)) if (!camino.includes(a)) buscar([...camino, a]);
})(["D"]);
todos.sort((p, q) => kmDe(p) - kmDe(q));
for (const c of todos) console.log(`  ${c.join("-")}  ${c.length - 1} tramos, ${kmDe(c)} km`);
